// Publishing illustration "How a piece of paper is made" (a four-step explainer, not part of the final video).
// Two objects, both following the same path as in the final video: print -> trace outline -> cut into a paper piece -> stand up.
//   daima: the code-drawn pedestrian - the one in a Hawaiian shirt waiting at the red light at the downtown intersection (5th at the intersection in downtown.js: campShirt, seed 484)
//   shengtu: the tourist generated by Codex - the one holding a red cup at the beach bar in the opening Keys scene (atlas keysPeople, 2nd cell)
// Steps 1 and 2: exportPngs() exports the texture and the traced outline directly as transparent-background PNGs (called by pipeline/web_export.py).
// Steps 3 and 4: this scene itself (rendered by web_stills / web_render):
//   t 0-3: the code-drawn figure flips up on a small piece of map paper (starts flipping at 0.5 s, same pop-up as in the final video: snapUp + slight twist + gentle sway); t 100-103: the generated-image figure, same thing
//   t 200: the code-drawn paper piece alone, 3/4 oblique angle, solid-color background (the style's base color), daytime light; t 201: the generated-image one
import * as THREE from "three";
import {traceAlpha, PopRegistry, polySheet, makeCanvas} from "./kit.js";
import {paintStreetPerson, LOOKS} from "./paint_people.js";
import {preloadAtlases, atlasCanvas, ATLASES} from "./atlas.js";
import * as K from "./props.js";

const PPM = 22;                 // print resolution of pedestrian standees in the final video (props.js)
const HI = 5;                   // redraw the code-drawn one at 5x resolution (same seed, same drawing); only 5x gets past 1080 wide
const CODE = {seed: 484, look: "campShirt"};
const ATLAS = {name: "keysPeople", cell: 2};
const T0 = 0.5;                 // flip-up time (within each segment)
const TRACE = {cell: 2, dilate: 1};   // same as props.js standee()

const codeCanvas = ppm => paintStreetPerson(ppm, CODE.seed, LOOKS[CODE.look]);
const atlasCard = ppm => atlasCanvas(ATLAS.name, ATLAS.cell, {ppm});

// ---------- Steps 1 and 2: texture, outline ----------
function withContour(src, ring, k, {line = 4, color = "#00e5ff", under = "#0b1838"} = {}) {
    const c = makeCanvas(src.width, src.height), g = c.getContext("2d");
    g.drawImage(src, 0, 0);
    g.lineJoin = "round";
    const path = new Path2D();
    ring.forEach(([x, y], i) => (i ? path.lineTo(x * k, y * k) : path.moveTo(x * k, y * k)));
    path.closePath();
    g.strokeStyle = under;
    g.lineWidth = line * 1.9;
    g.stroke(path);
    g.strokeStyle = color;
    g.lineWidth = line;
    g.stroke(path);
    return c;
}
function enlarge(src, k) {
    const c = makeCanvas(src.width * k, src.height * k), g = c.getContext("2d");
    g.imageSmoothingQuality = "high";
    g.drawImage(src, 0, 0, c.width, c.height);
    return c;
}
export async function exportPngs() {
    await preloadAtlases();
    const out = {};
    const png = c => c.toDataURL("image/png");
    // Code-drawn: as in the final video (22 px/mm) + a 5x redraw; outlines all come from the final-video version (that ring is what gets cut), scaled up proportionally on the 5x image
    const code = codeCanvas(PPM), codeHi = codeCanvas(PPM * HI);
    const codeRing = traceAlpha(code, TRACE);
    out["1_print_code_raw.png"] = png(code);
    out[`1_print_code_${HI}x.png`] = png(codeHi);
    out["2_trace_code_raw.png"] = png(withContour(code, codeRing, 1, {line: 1.6}));
    out[`2_trace_code_${HI}x.png`] = png(withContour(codeHi, codeRing, HI, {line: 7}));
    // Generated image: as in the final video (cut from the atlas cell, white background removed, scaled to 22 px/mm at the common scale, about 1:1 with the source image); it only has as many pixels as the source, so 5x is an upscale, not a redraw
    const at = atlasCard(PPM);
    const atRing = traceAlpha(at, TRACE);
    out["1_print_gen_raw.png"] = png(at);
    out[`1_print_gen_zoom${HI}x.png`] = png(enlarge(at, HI));
    out["2_trace_gen_raw.png"] = png(withContour(at, atRing, 1, {line: 1.6}));
    out[`2_trace_gen_zoom${HI}x.png`] = png(withContour(enlarge(at, HI), atRing, HI, {line: 7}));
    // The whole atlas, with the cell in use boxed (the generated image is one whole 7x3 sheet generated together; the program cuts it by cell)
    const spec = ATLASES[ATLAS.name], img = new Image();
    img.src = spec.url;
    await img.decode();
    const sheet = makeCanvas(img.width, img.height), g = sheet.getContext("2d");
    g.drawImage(img, 0, 0);
    const cw = img.width / spec.cols, ch = img.height / spec.rows, c = ATLAS.cell % spec.cols, r = Math.floor(ATLAS.cell / spec.cols);
    g.lineWidth = 6;
    g.strokeStyle = "#00e5ff";
    g.strokeRect(c * cw + 4, r * ch + 4, cw - 8, ch - 8);
    out["1_print_gen_sheet.png"] = png(sheet);
    return out;
}

// ---------- Steps 3 and 4: scene ----------
export async function build() {
    const root = new THREE.Group();
    await preloadAtlases();
    const pops = new PopRegistry();
    const items = [
        {g: K.streetPerson("steps_code", CODE.seed, CODE.look), base: 0, card: 200},
        {g: K.atlasPerson("steps_gen", atlasCard(PPM)), base: 100, card: 201},
    ].map(it => {
        const pivot = new THREE.Group(), holder = new THREE.Group();
        holder.add(it.g);
        pivot.add(holder);
        root.add(pivot);
        pops.add(pivot, {t0: it.base + T0});
        return {...it, pivot, holder};
    });
    // A small piece of map paper (daytime sand color, the style gives it paper texture); the single-paper-piece shots leave it out
    // It has to be big enough: at 120 square the paper edge and the purple background behind show at the top of the frame
    const ground = polySheet([[-800, -800], [800, -800], [800, 800], [-800, 800]], {id: "steps_ground", color: "#f2d6b0", thickness: 1, castShadow: false});
    ground.position.z = -0.5;
    ground.userData.paper.meta.mat.front.ground = true;
    root.add(ground);

    const cam = (pos, tgt, fov) => {
        const d = Math.hypot(pos[0] - tgt[0], pos[1] - tgt[1], pos[2] - tgt[2]);
        return {position: pos, target: tgt, up: [0, 0, 1], fov, near: 1, far: 2000, focus: {distance: d, band: 400, tilt: 0, maxBlur: 0}};
    };
    function camera(t) {
        if (t >= 200) {
            // 3/4 oblique angle: viewed from the front right at 40 deg, tilted slightly down, so the cut edge on the right (light paper core) is visible
            const a = 40 * Math.PI / 180, d = 40;
            return cam([d * Math.sin(a), -d * Math.cos(a), 11], [0, 0, 7.2], 28);
        }
        return cam([20, -44, 30], [0, 3, 6], 30);
    }
    function update({t}) {
        const card = t >= 200;
        pops.update(card ? 1e4 : t);
        for (const it of items) {
            const local = t - it.base;
            it.holder.visible = card ? Math.round(t) === it.card : local >= 0 && local < 100;
            // Same as the final video: the standee figure sways gently (the single paper piece does not sway)
            it.holder.rotation.y = card ? 0 : Math.sin(local * 1.7 + 0.8) * 0.035;
        }
        ground.visible = !card;
    }
    return {root, camera, update, state: t => ({t, tod: 0, focus: [0, 0, 0]})};
}
